INSERT INTO changelog_entries(version,title,summary,content,category,published_at,affected_route,created_at,updated_at) SELECT '2.59.0','Premium планове, местен час за известия и адаптивни карти','Изберете час за дневния отчет и сравнете абонаментите с реални годишни спестявания.','["Дневните AI известия следват избран час от 00:00 до 23:00 в часовата зона на държавата за финансиране, с начална стойност 10:00 и автоматично лятно часово време.","Premium показва актуалните администраторски цени и изчислява годишното спестяване само когато има реална отстъпка.","Дългите преводи остават в рамките на картите. Запази и Сравни са в общ ред, а детайлите и профилът се адаптират към екрана."]','improvement','2026-09-20','/profile',datetime('now'),datetime('now') WHERE NOT EXISTS (SELECT 1 FROM changelog_entries WHERE version='2.59.0');
